-- Linked evidence, constraints and transactional candidate acceptance, including backend writers.
select no_plan();
select tests.create_import_fixture();
select ok(not has_function_privilege('anon','public.accept_design_candidate(uuid,text,text,text)','EXECUTE'), 'public requests have no acceptance capability');
select ok(has_function_privilege('authenticated','public.accept_design_candidate(uuid,text,text,text)','EXECUTE'), 'authenticated users can reach the guarded acceptance RPC');
select ok(not has_function_privilege('authenticated','private.create_candidate_effect(uuid,text,jsonb,text,uuid)','EXECUTE'), 'internal effect creation is not an API capability');
set local role service_role;
select throws_ok($query$insert into public.imports(supplier_id,media_id,stage) values ('20000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000006','uploaded')$query$, '23514', null, 'backend cannot attach a foreign supplier price list');
select throws_ok($query$insert into public.imports(supplier_id,media_id,stage) values ('20000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','uploaded')$query$, '23514', null, 'imports require price-list media');
select throws_ok($query$update public.imports set supplier_id = '20000000-0000-0000-0000-000000000002', media_id = '30000000-0000-0000-0000-000000000006' where id = '80000000-0000-0000-0000-000000000001'$query$, '23514', null, 'submission identity cannot be reassigned');
select throws_ok($query$update public.import_lines set supplier_product_id = (select id from public.supplier_products where supplier_id = '20000000-0000-0000-0000-000000000002') where id = '81000000-0000-0000-0000-000000000001'$query$, '23514', null, 'matched listing cannot cross supplier boundary');
select lives_ok($query$update public.import_lines set supplier_product_id = (select id from public.supplier_products where supplier_id = '20000000-0000-0000-0000-000000000001') where id = '81000000-0000-0000-0000-000000000001'$query$, 'matching own supplier listing succeeds');
select throws_ok($query$update public.import_lines set confidence = 1.01 where id = '81000000-0000-0000-0000-000000000001'$query$, '23514', null, 'confidence is a normalised probability');
select throws_ok($query$insert into public.import_lines(import_id,row_number,raw,state) values ('80000000-0000-0000-0000-000000000001',1,'{}','new')$query$, '23505', null, 'line numbers are unique per import');
select throws_ok($query$update public.import_lines set row_number = 0 where id = '81000000-0000-0000-0000-000000000001'$query$, '23514', null, 'line numbering starts at one');
select throws_ok($query$update public.import_lines set decided_at = now() where id = '81000000-0000-0000-0000-000000000001'$query$, '23514', null, 'decision timestamp requires attribution');
select throws_ok($query$update public.supplier_products set last_import_id = 'ffffffff-ffff-ffff-ffff-ffffffffffff'$query$, '23503', null, 'listing import reference rejects unknown imports');
select throws_ok($query$update public.supplier_products set last_import_id = '80000000-0000-0000-0000-000000000002' where supplier_id = '20000000-0000-0000-0000-000000000001'$query$, '23503', null, 'listing import reference rejects another supplier');
select lives_ok($query$update public.supplier_products set last_import_id = '80000000-0000-0000-0000-000000000001' where supplier_id = '20000000-0000-0000-0000-000000000001'$query$, 'listing records an import from its supplier');
select throws_ok($query$update public.product_versions set candidate_id = 'ffffffff-ffff-ffff-ffff-ffffffffffff' where id = '70000000-0000-0000-0000-000000000002'$query$, '23503', null, 'product candidate reference rejects unknown candidates');
select throws_ok($query$insert into public.video_analyses(media_id,extractor) values ('30000000-0000-0000-0000-000000000005','fixture')$query$, '23514', null, 'analysis rejects non-video media');
select throws_ok($query$update public.video_analyses set supplier_product_id = (select id from public.supplier_products where supplier_id = '20000000-0000-0000-0000-000000000002') where id = '82000000-0000-0000-0000-000000000001'$query$, '23514', null, 'analysis rejects foreign supplier listing');
select lives_ok($query$update public.video_analyses set supplier_product_id = (select id from public.supplier_products where supplier_id = '20000000-0000-0000-0000-000000000001') where id = '82000000-0000-0000-0000-000000000001'$query$, 'analysis accepts consistent video product listing');
select throws_ok($query$update public.video_analyses set product_id = '60000000-0000-0000-0000-000000000002' where id = '82000000-0000-0000-0000-000000000001'$query$, '23514', null, 'analysis rejects conflicting product priors');
select throws_ok($query$update public.design_candidates set parent_id = '83000000-0000-0000-0000-000000000002' where id = '83000000-0000-0000-0000-000000000001'$query$, '23503', null, 'candidate parent must share analysis');
select throws_ok($query$update public.design_candidates set parent_id = id where id = '83000000-0000-0000-0000-000000000001'$query$, '23514', null, 'candidate cannot refine itself');
select throws_ok($query$update public.design_candidates set overall = 1.001 where id = '83000000-0000-0000-0000-000000000001'$query$, '23514', null, 'candidate score is normalised');
select lives_ok($query$insert into public.design_candidates(analysis_id,parent_id,source,proposal,renderer) values ('82000000-0000-0000-0000-000000000001','83000000-0000-0000-0000-000000000001','fit',tests.candidate_proposal(),'fixture')$query$, 'fitted refinement shares analysis');
select throws_ok($query$insert into public.reviews(reviewer_id,decision) values (tests.get_supabase_uid('platform_staff'),'comment')$query$, '23514', null, 'review must target a version');
select throws_ok($query$insert into public.reviews(effect_version_id,product_version_id,reviewer_id,decision) values ('50000000-0000-0000-0000-000000000002','70000000-0000-0000-0000-000000000002',tests.get_supabase_uid('platform_staff'),'approved')$query$, '23514', null, 'review targets exactly one version');
select lives_ok($query$insert into public.reviews(product_version_id,reviewer_id,decision,reasons) values ('70000000-0000-0000-0000-000000000002',tests.get_supabase_uid('platform_staff'),'changes_requested',array['timing'])$query$, 'product review stores structured reasons');
select is((select status from public.product_versions where id = '70000000-0000-0000-0000-000000000002'), 'draft', 'review recording does not publish or change history');
reset role;
select tests.act_as('other_organisation_member');
select throws_ok($query$select public.accept_design_candidate('83000000-0000-0000-0000-000000000001')$query$, '42501', null, 'another organisation cannot accept candidates');
reset role;
select tests.act_as('supplier_member');
select throws_ok($query$select public.accept_design_candidate('83000000-0000-0000-0000-000000000001')$query$, '42501', null, 'supplier cannot author canonical designs');
reset role;
update public.staff_roles set role = 'reviewer' where profile_id = tests.get_supabase_uid('platform_staff');
select tests.act_as('platform_staff');
select throws_ok($query$select public.accept_design_candidate('83000000-0000-0000-0000-000000000001')$query$, '42501', null, 'reviewer cannot accept designs');
reset role;
update public.staff_roles set role = 'catalogue_editor' where profile_id = tests.get_supabase_uid('platform_staff');
select tests.act_as('platform_staff');
select throws_ok($query$select public.accept_design_candidate('ffffffff-ffff-ffff-ffff-ffffffffffff')$query$, 'P0002', null, 'unknown candidate is an explicit error');
select lives_ok($query$select public.accept_design_candidate('83000000-0000-0000-0000-000000000001')$query$, 'editor accepts a ready candidate for existing product');
select is((select count(*) from public.product_versions where candidate_id = '83000000-0000-0000-0000-000000000001'), 1::bigint, 'acceptance creates one provenance-linked version');
select is((select source from public.product_versions where candidate_id = '83000000-0000-0000-0000-000000000001'), 'video_import', 'accepted version records source');
select is((select status from public.product_versions where candidate_id = '83000000-0000-0000-0000-000000000001'), 'draft', 'accepted version remains draft');
select is((select number from public.product_versions where candidate_id = '83000000-0000-0000-0000-000000000001'), 2, 'version numbering follows existing history');
select is((select current_version_id from public.products where id = '60000000-0000-0000-0000-000000000001'), '70000000-0000-0000-0000-000000000001'::uuid, 'acceptance preserves published product pointer');
select is((select composition from public.product_versions where candidate_id = '83000000-0000-0000-0000-000000000001'), tests.composition_fixture(), 'measured composition is preserved');
select is((select count(*) from public.effects where slug like 'video-83000000-0000-0000-0000-000000000001-%' and status = 'draft'), 1::bigint, 'acceptance creates a draft effect');
select is((select design#>>'{launch,height_m}' from public.effect_versions where effect_id = (select id from public.effects where slug = 'video-83000000-0000-0000-0000-000000000001-a')), '70', 'nested overrides apply to template');
select is((select design#>'{launch,time_s}' from public.effect_versions where effect_id = (select id from public.effects where slug = 'video-83000000-0000-0000-0000-000000000001-a')), tests.design_fixture()#>'{launch,time_s}', 'nested overrides preserve unspecified fields');
select is((select reference_media_id from public.effect_versions where effect_id = (select id from public.effects where slug = 'video-83000000-0000-0000-0000-000000000001-a')), '30000000-0000-0000-0000-000000000001'::uuid, 'effect records video reference');
select is((select renderer from public.effect_versions where effect_id = (select id from public.effects where slug = 'video-83000000-0000-0000-0000-000000000001-a')), 'fixture', 'effect records candidate renderer');
select is((select author_id from public.product_versions where candidate_id = '83000000-0000-0000-0000-000000000001'), tests.get_supabase_uid('platform_staff'), 'acceptance records editor author');
select is(public.accept_design_candidate('83000000-0000-0000-0000-000000000001'), (select id from public.product_versions where candidate_id = '83000000-0000-0000-0000-000000000001'), 'retry returns same version');
select is((select count(*) from public.effects where slug like 'video-83000000-0000-0000-0000-000000000001-%'), 1::bigint, 'retry creates no duplicate effects');
select throws_ok($query$update public.design_candidates set proposal = '{}' where id = '83000000-0000-0000-0000-000000000001'$query$, '23514', null, 'accepted proposal cannot be rewritten');
select throws_ok($query$delete from public.design_candidates where id = '83000000-0000-0000-0000-000000000001'$query$, '23514', null, 'accepted proposal cannot be deleted');
select lives_ok($query$select public.accept_design_candidate('83000000-0000-0000-0000-000000000002','reconstructed-product','Reconstructed product','cake')$query$, 'candidate can create a new product');
select is((select safety_confirmed_by from public.products where slug = 'reconstructed-product'), null::uuid, 'video acceptance never confirms safety');
select is((select current_version_id from public.products where slug = 'reconstructed-product'), null::uuid, 'new reconstructed product is unpublished');
reset role;
set local role service_role;
select throws_ok($query$update public.design_candidates set renderer = 'rewritten' where id = '83000000-0000-0000-0000-000000000001'$query$, '23514', null, 'backend cannot rewrite accepted provenance');
select throws_ok($query$update public.video_analyses set shots = '[]' where id = '82000000-0000-0000-0000-000000000001'$query$, '23514', null, 'backend cannot rewrite accepted video evidence');
reset role;
select tests.act_as_public();
select is((select count(*) from public.products), 2::bigint, 'acceptance does not expose a new product publicly');
select is((select count(*) from public.effects), 1::bigint, 'acceptance does not expose draft effects publicly');
reset role;
select * from finish();
